* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Segoe UI', sans-serif;
  background: #1a1a2e;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.chat-container {
  background: #16213e;
  border-radius: 12px;
  width: 100%;
  max-width: 560px;
  height: 90vh;
  max-height: 640px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
}

.chat-header {
  background: #0f3460;
  padding: 16px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.chat-header h1 { color: #e2e8f0; font-size: 1.1em; }

.status-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  transition: background 0.3s;
}
.status-dot.online  { background: #48bb78; }
.status-dot.offline { background: #fc8181; }

.name-setup {
  display: flex;
  gap: 10px;
  padding: 20px;
  flex: 1;
  align-items: center;
  justify-content: center;
}

.chat-area {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
}

.messages {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.message {
  background: #0f3460;
  border-radius: 8px;
  padding: 8px 12px;
  max-width: 85%;
  word-break: break-word;
}

.message.mine {
  background: #533483;
  align-self: flex-end;
}

.message .author {
  font-size: 0.75em;
  color: #90cdf4;
  margin-bottom: 2px;
  font-weight: 600;
}

.message .text { color: #e2e8f0; font-size: 0.92em; }
.message .time { font-size: 0.7em; color: #718096; margin-top: 2px; }

.message.system {
  background: transparent;
  align-self: center;
  font-size: 0.78em;
  color: #718096;
  font-style: italic;
}

/* -- Pending message states -- */

@keyframes pendingPulse {
  0%, 100% { opacity: 0.55; box-shadow: 0 0 0 0 rgba(99, 179, 237, 0); }
  50%       { opacity: 0.8;  box-shadow: 0 0 8px 2px rgba(99, 179, 237, 0.25); }
}

@keyframes spinnerRotate {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.pending-message {
  animation: pendingPulse 1.4s ease-in-out infinite;
  border: 1px solid rgba(99, 179, 237, 0.3);
}

.pending-failed {
  animation: none;
  opacity: 0.9;
  border: 1px solid rgba(252, 129, 129, 0.5);
  background: #3d1f2a !important;
}

.pending-confirmed {
  animation: none;
  opacity: 0.9;
  border: 1px solid rgba(72, 187, 120, 0.4);
}

.pending-status {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 4px;
  font-size: 0.7em;
  color: #718096;
}

.pending-label { color: #718096; }

.pending-failed  .pending-label { color: #fc8181; }
.pending-confirmed .pending-label { color: #68d391; }

.pending-icon {
  font-size: 0.9em;
  line-height: 1;
}

.pending-spinner {
  display: inline-block;
  width: 10px;
  height: 10px;
  border: 1.5px solid rgba(99, 179, 237, 0.3);
  border-top-color: #63b3ed;
  border-radius: 50%;
  animation: spinnerRotate 0.7s linear infinite;
  flex-shrink: 0;
}

.pending-retry {
  background: transparent;
  border: 1px solid #fc8181;
  color: #fc8181;
  padding: 1px 7px;
  border-radius: 3px;
  cursor: pointer;
  font-size: 0.85em;
  margin-left: 4px;
  transition: all 0.15s;
}

.pending-retry:hover {
  background: #fc8181;
  color: #1a1a2e;
}

/* -- Input row -- */

.input-row {
  display: flex;
  gap: 8px;
  padding: 12px 16px;
  background: #0f3460;
}

input {
  flex: 1;
  background: #1a1a2e;
  border: 1px solid #2d3748;
  border-radius: 6px;
  padding: 8px 12px;
  color: #e2e8f0;
  font-size: 0.95em;
}

input:focus { outline: none; border-color: #63b3ed; }

button {
  background: #4299e1;
  color: white;
  border: none;
  padding: 8px 18px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.95em;
  white-space: nowrap;
}

button:hover { background: #3182ce; }

// -- Config --------------------------------------------------------------
const pth = window.location.pathname;
const API_BASE = window.origin + pth.substr(0,pth.length-1);
const POLL_INTERVAL_MS = 2000;
// ------------------------------------------------------------------------

let myName = '';
let pollTimer = null;

// Confirmed messages from server
let confirmedMessages = [];

// Pending messages (optimistic, not yet confirmed by server)
// Each: { tempId, author, text, ts, status: 'pending'|'failed' }
let pendingMessages = [];

let tempIdCounter = 0;

function joinChat() {
  const name = document.getElementById('nameInput').value.trim();
  if (!name) return;
  myName = name;
  document.getElementById('nameSetup').style.display = 'none';
  document.getElementById('chatArea').style.display = 'flex';
  document.getElementById('msgInput').focus();
  startPolling();
  postSystemMessage(`${myName} joined the chat`);
}

async function sendMessage() {
  const input = document.getElementById('msgInput');
  const text  = input.value.trim();
  if (!text || !myName) return;
  input.value = '';

  // Optimistic: add to pending immediately
  const tempId = ++tempIdCounter;
  const pending = { tempId, author: myName, text, ts: Date.now(), status: 'pending' };
  pendingMessages.push(pending);
  renderAll();

  try {
    const res = await fetch(`${API_BASE}/messages`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ author: myName, text })
    });
    if (!res.ok) throw new Error('Server error');
    // Server confirmed — the next poll will pick it up and we remove the pending
    // Mark as confirmed locally so it fades out gracefully before poll arrives
    pending.status = 'confirmed';
    renderAll();
  } catch (e) {
    // Mark as failed
    pending.status = 'failed';
    renderAll();
  }
}

async function retryPending(tempId) {
  const pending = pendingMessages.find(p => p.tempId === tempId);
  if (!pending) return;
  pending.status = 'pending';
  renderAll();

  try {
    const res = await fetch(`${API_BASE}/messages`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ author: pending.author, text: pending.text })
    });
    if (!res.ok) throw new Error('Server error');
    pending.status = 'confirmed';
    renderAll();
  } catch (e) {
    pending.status = 'failed';
    renderAll();
  }
}

async function postSystemMessage(text) {
  try {
    await fetch(`${API_BASE}/messages`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ author: '__system__', text })
    });
  } catch (e) { /* silent */ }
}

function startPolling() {
  poll();
  pollTimer = setInterval(poll, POLL_INTERVAL_MS);
}

async function poll() {
  try {
    const res = await fetch(`${API_BASE}/messages`);
    if (!res.ok) throw new Error('Server error');
    const data = await res.json();
    const msgs = data.messages || [];
    setOnline(true);

    if (msgs.length !== confirmedMessages.length) {
      confirmedMessages = msgs;

      // Remove pending messages that now appear in confirmed list
      // Match by author + text (server may reorder slightly but unlikely)
      pendingMessages = pendingMessages.filter(p => {
        if (p.status === 'failed') return true; // keep failed ones visible
        const found = confirmedMessages.some(
          c => c.author === p.author && c.text === p.text
        );
        return !found; // remove if confirmed
      });

      renderAll();
    }
  } catch (e) {
    setOnline(false);
  }
}

function renderAll() {
  const container = document.getElementById('messages');
  const wasAtBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 40;

  container.innerHTML = '';

  // Render confirmed messages
  confirmedMessages.forEach(m => {
    container.appendChild(buildConfirmedMessage(m));
  });

  // Render pending messages (optimistic, not yet in server list)
  pendingMessages.forEach(p => {
    // Don't show 'confirmed' pending ones if they already appear in confirmed list
    if (p.status === 'confirmed') {
      const alreadyIn = confirmedMessages.some(
        c => c.author === p.author && c.text === p.text
      );
      if (alreadyIn) return;
    }
    container.appendChild(buildPendingMessage(p));
  });

  if (wasAtBottom) container.scrollTop = container.scrollHeight;
}

function buildConfirmedMessage(m) {
  const div = document.createElement('div');
  if (m.author === '__system__') {
    div.className = 'message system';
    div.textContent = m.text;
  } else {
    div.className = 'message' + (m.author === myName ? ' mine' : '');
    div.innerHTML = `
      <div class="author">${escHtml(m.author)}</div>
      <div class="text">${escHtml(m.text)}</div>
      <div class="time">${new Date(m.ts).toLocaleTimeString()}</div>
    `;
  }
  return div;
}

function buildPendingMessage(p) {
  const div = document.createElement('div');
  const isFailed  = p.status === 'failed';
  const isConfirmed = p.status === 'confirmed';

  div.className = 'message mine pending-message' +
    (isFailed   ? ' pending-failed'    : '') +
    (isConfirmed ? ' pending-confirmed' : '');

  const statusIcon = isFailed
    ? `<span class="pending-icon" title="Failed to send">⚠️</span>`
    : isConfirmed
      ? `<span class="pending-icon" title="Delivered">✓</span>`
      : `<span class="pending-icon pending-spinner" title="Sending..."></span>`;

  const retryBtn = isFailed
    ? `<button class="pending-retry" onclick="retryPending(${p.tempId})">Retry</button>`
    : '';

  div.innerHTML = `
    <div class="author">${escHtml(p.author)}</div>
    <div class="text">${escHtml(p.text)}</div>
    <div class="pending-status">
      ${statusIcon}
      <span class="pending-label">${
        isFailed ? 'Failed to send' : isConfirmed ? 'Delivered' : 'Sending...'
      }</span>
      ${retryBtn}
    </div>
  `;
  return div;
}

function setOnline(online) {
  const dot = document.getElementById('statusDot');
  dot.className = 'status-dot ' + (online ? 'online' : 'offline');
  dot.title = online ? 'Server connected' : 'Server offline';
}

function escHtml(str) {
  return String(str)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;')
    .replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('nameInput').addEventListener('keydown', e => {
    if (e.key === 'Enter') joinChat();
  });
  document.getElementById('msgInput').addEventListener('keydown', e => {
    if (e.key === 'Enter') sendMessage();
  });
});

// FORGE Chatroom Server
// Runs in the Server Console tab via ForgeAPI.
// Stores messages in memory — they reset when the server stops.
//
// HOW TO USE:
//   1. Click the 🖥️ icon next to server.js in the Files tab
//   2. Switch to the Server Console tab
//   3. Click ▶ Start Server
//   4. Switch back to Preview tab — the chat is live!
//   5. Share the Short URL so others can join

const MAX_MESSAGES = 200;
const messages = [];
const servePath='/sandbox/chatroom' + (Math.random()+"").split(".")[1];

const api = ForgeAPI.create(servePath);


// GET /messages — return all messages
api.get('/messages', (req) => {
  return {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
    body: { messages }
  };
});

// POST /messages — add a new message
api.post('/messages', (req) => {
  const { author, text } = req.body || {};

  if (!author || !text) {
    return {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
      body: { error: 'author and text are required' }
    };
  }

  messages.push({
    author: String(author).substring(0, 32),
    text:   String(text).substring(0, 500),
    ts:     Date.now()
  });

  // Keep only the last MAX_MESSAGES
  if (messages.length > MAX_MESSAGES) {
    messages.splice(0, messages.length - MAX_MESSAGES);
  }

  return {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
    body: { ok: true, count: messages.length }
  };
});

api.get('/', (req) => {
    return self.ForgeAPI.vfs.readFile("index.html")
           .then(a=>{
             var mt=a.mimeType;
             var cont=a.content;
             var rr={
                status: 200,
                headers: { 'Content-Type': mt },
                body: cont
             };
             return rr;
           });
});

api.get('/*', (req) => {
    return self.ForgeAPI.vfs.readFile(req.path)
           .then(a=>{
             var mt=a.mimeType;
             var cont=a.content;
             var rr={
                status: 200,
                headers: { 'Content-Type': mt },
                body: cont
             };
             return rr;
           });
});


api.start();
console.log('Chatroom server started at ' + servePath);
console.log('GET  ' + servePath + '/messages — fetch messages');
console.log('POST ' + servePath + '/messages — send a message');
